'use strict';

const orders = [];

function listOrders() {
  return orders;
}

async function saveOrder(order) {
  if (!order || !order.id) {
    throw new Error('order requires an id');
  }
  if (!(order.total > 0)) {
    throw new Error('order total must be positive');
  }
  orders.push(order);
  return order;
}

module.exports = { orders, listOrders, saveOrder };
